-- ============================================================
-- WONDER AQUA — STEP 2 of 4 : USER ACCOUNTS (run AFTER step 1)
-- Same UUIDs + password hashes, so everyone signs in unchanged.
-- ============================================================
SET session_replication_role = replica;

-- Auth users & identities (passwords preserved)



SET session_replication_role = origin;

-- Recreate the two auth triggers the app relies on
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
DROP TRIGGER IF EXISTS on_auth_user_created_superadmin ON auth.users;
CREATE TRIGGER on_auth_user_created_superadmin AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_superadmin_assignment();
